SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, DATE_TRUNC('YEAR', started_at) AS year_start, browser, COUNT_IF(country = 'US') AS us_events, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, COUNT(*) FILTER (WHERE device = 'mobile') AS mobile_rows, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', started_at) ORDER BY COUNT(*) FILTER (WHERE device = 'mobile') DESC) AS mobile_rows_dense_rank FROM sessions GROUP BY quarter_start, year_start, browser ORDER BY mobile_rows NULLS LAST;
